begin;

update portfolio.publications set sort = 2 where kind = 'Patent' and id_value = '202511053637';

insert into portfolio.publications (sort, kind, title, authors, venue, date_label, year, id_label, id_value, abstract, href, image, tags) values
  (0, 'Preprint', 'Enforcing Data Authorization Below the Model: An Experience Report on a Production LLM Analytics Assistant for Enterprise Chat', array['Mohammad Ramiz']::text[], 'ResearchGate · Independent research', 'November 2026', 2026, null, null, 'An experience report on a production assistant that answers business questions inside an enterprise chat platform by having an LLM write SQL against a cloud data warehouse. It argues that authorization must be enforced by a deterministic policy layer below the model, with anything the model is told about permissions treated as an efficiency measure rather than a control. It formalises the injected row-level predicate as monotone-narrowing, separates authorizing the identifiers a query names from expanding a grant into a filter, and adds a grounding rail that checks the tool-call record rather than the prose, because a sentence with a fabricated number reads exactly like one with a real number. It also compares building the same service with and without permission to change the schema, pins the guarantees lost to that constraint with negative tests, and reports nine field incidents and how each was closed.', 'https://www.researchgate.net/publication/417293234_Enforcing_Data_Authorization_Below_the_Model_An_Experience_Report_on_a_Production_LLM_Analytics_Assistant_for_Enterprise_Chat', null, array['LLMs', 'Text-to-SQL', 'Access control', 'Row-level security', 'Guardrails']::text[]),
  (1, 'Preprint', 'bakup: A Git-Inspired, Offline-First Personal Backup System with Content-Addressed Cross-Repository Deduplication', array['Mohammad Ramiz']::text[], 'ResearchGate · Independent research', 'July 2026', 2026, null, null, 'bakup is a self-hosted backup system that brings Git''s interaction model to whole-directory backup: initialise any folder as a repository, commit snapshots entirely offline, push them to a personally owned server when it is reachable, and restore any past state on any machine with a single clone. It combines a metadata-only local snapshot log, an mtime/size stat cache that avoids re-hashing unchanged files, set-difference transfer negotiation, and a global content-addressed object store with SHA-256 deduplication across all repositories and clients. On a 150.8 MB, 1,206-file workload it stores the first snapshot at 68.5% of logical size, propagates a 1% change in 0.29 s by sending 1.08 MB, deduplicates 82.3% of a second repository sharing half its content, and restores a byte-identical copy in 6.6 s, in roughly 700 lines of Python and a single Docker container.', 'https://www.researchgate.net/publication/409147519_bakup_A_Git-Inspired_Offline-First_Personal_Backup_System_with_Content-Addressed_Cross-Repository_Deduplication', null, array['Backup', 'Content addressing', 'Deduplication', 'Offline-first', 'Self-hosting']::text[]),
  (3, 'Conference paper', 'The Talk of Realities: Augmented, Virtual, Extended — The Future', array['Mohammad Ramiz']::text[], 'Conference on Augmented Reality · Greater Noida', 'February 2025', 2025, null, null, 'A look at the emerging world of multiple realities (AR, VR and XR). As more of everyday interaction moves to virtual channels, these technologies use cameras and depth sensors to blend virtual components with the real world. The paper discusses why they are growing so quickly, as people spend less time interacting in person and more through their devices, and how they are changing the way people communicate with one another.', 'https://www.researchgate.net/publication/388764021_The_Talk_of_Realities_Augmented_Virtual_Extended_The_Future', null, array['Augmented reality', 'Virtual reality', 'Extended reality']::text[]);

commit;
